// Regenerates public/block-icons.css from config/block-sprites.json.
// Coordinates point into public/images/items.png (32px grid), the icons are
// rendered at 20px so every offset is scaled by 20/32.
const fs = require('fs');
const path = require('path');

const sprites = require('../config/block-sprites.json');

const SPRITE_SIZE = 864;
const CELL_SIZE = 32;
const ICON_SIZE = 20;
const SCALE = ICON_SIZE / CELL_SIZE;

const lines = [
  '/* Generated by scripts/generate-block-icons-css.js from config/block-sprites.json. Do not edit by hand. */',
  '.bh-block-icon {',
  '  display: inline-block;',
  `  width: ${ICON_SIZE}px;`,
  `  height: ${ICON_SIZE}px;`,
  '  background: url(images/items.png) no-repeat;',
  `  background-size: ${SPRITE_SIZE * SCALE}px ${SPRITE_SIZE * SCALE}px;`,
  '  image-rendering: pixelated;',
  '  vertical-align: text-bottom;',
  '  margin-right: 6px;',
  '}',
  '',
];

Object.entries(sprites).forEach(([material, { x, y }]) => {
  lines.push(`.bh-icon-${material.toLowerCase()} { background-position: -${x * SCALE}px -${y * SCALE}px; }`);
});

fs.writeFileSync(path.resolve(__dirname, '../public/block-icons.css'), lines.join('\n') + '\n');

console.log(`Generated block-icons.css with ${Object.keys(sprites).length} icons`);
